package com.pixilife.android;
import android.content.*;import java.util.*;
public final class PersonalityManager {private final android.content.SharedPreferences p;public PersonalityManager(Context c){p=c.getSharedPreferences("personality",Context.MODE_PRIVATE);if(!p.contains("base"))reset();}public String current(){return p.getString("current","divertido");}public void set(String x){p.edit().putString("current",x).putString("base",x).apply();}public void reset(){p.edit().putString("current","divertido").putString("base","divertido").putBoolean("evolution",true).putFloat("playfulness",.7f).putFloat("formality",.25f).putFloat("curiosity",.75f).putFloat("technicality",.5f).putFloat("affection",.7f).putFloat("sarcasm",.45f).apply();}public boolean evolution(){return p.getBoolean("evolution",true);}public void evolution(boolean on){p.edit().putBoolean("evolution",on).apply();}public void observe(String text){if(!evolution())return;String t=text.toLowerCase(Locale.ROOT);android.content.SharedPreferences.Editor e=p.edit();adjust(e,"technicality",(t.contains("código")||t.contains("como funciona"))?.006f:-.001f);adjust(e,"playfulness",(t.contains("jaja")||t.contains("broma"))?.006f:-.001f);adjust(e,"affection",(t.contains("gracias")||t.contains("quiero"))?.004f:0);adjust(e,"curiosity",.001f);e.apply();}private void adjust(android.content.SharedPreferences.Editor e,String k,float d){e.putFloat(k,Math.max(0,Math.min(1,p.getFloat(k,.5f)+d)));}public String profile(){return "Personalidad "+current()+"; juego "+p.getFloat("playfulness",.5f)+", formalidad "+p.getFloat("formality",.5f)+", curiosidad "+p.getFloat("curiosity",.5f)+", técnica "+p.getFloat("technicality",.5f)+", cariño "+p.getFloat("affection",.5f)+", sarcasmo "+p.getFloat("sarcasm",.5f)+".";}}
